  ],
  "claims": [
    {
      "paragraph": 1,
      "text": "История этого места связана с Василием Аршиновым",
      "factIds": ["m3_f2"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "который заказал Михаилу Шехтелю институт для своего сына Владимира",
      "factIds": ["m3_f2"],
      "supported": false
    },
    {
      "paragraph": 1,
      "text": "Владимир Аршинов окончил Московский университет",
      "factIds": ["m3_f2"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "был учеником Владимира Вернадского",
      "factIds": ["m3_f2"],
      "supported": false
    },
    {
      "paragraph": 1,
      "text": "Аршинов также поддерживал коммерческое образование и приходскую школу",
      "factIds": ["m3_f1"],
      "supported": false
    },
    {
      "paragraph": 2,
      "text": "Основание «Литогеи» заложили в 1904 году",
      "factIds": ["m3_f2"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "от неё ВИМС ведёт свою историю",
      "factIds": ["m3_f2"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Научный корпус построили в 1904–1905 годах по проекту Шехтеля",
      "factIds": ["m3_f1"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Он находился в глубине владения",
      "factIds": ["m3_f1"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "с улицы был скрыт другими постройками",
      "factIds": ["m3_f1"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "поэтому за купеческим фасадом оставалось незаметное научное учреждение",
      "factIds": ["m3_f1", "m3_f2"],
      "supported": false
    }
  ]
}

