  ],
  "claims": [
    {
      "paragraph": 1,
      "text": "Кожевнический проезд и переулки сохранили в названиях память о слободе кожевников",
      "factIds": ["leather-settlement"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "сформировавшейся на берегу Москвы-реки в XVI веке",
      "factIds": ["leather-settlement", "sixteenth-century"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "Здесь выделывали кожи.",
      "factIds": ["leather-settlement"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "В старом путеводителе Кожевническая и Ивановская указаны как два названия одной улицы.",
      "factIds": ["ivanovskaya"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Старейшим сохранившимся зданием слободы считаются палаты на Кожевнической улице.",
      "factIds": ["chambers"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Это кирпичный двухэтажный дом конца XVII века",
      "factIds": ["chambers"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "стоящий в глубине владения ближе к реке",
      "factIds": ["chambers"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Его отличают кубический объём, крыша с высокими дымниками и узкие окна.",
      "factIds": ["chambers"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Первоначальное назначение палат доподлинно неизвестно.",
      "factIds": ["chambers"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "После упразднения Петром I слободского устройства здесь разместился мытный двор — городская таможня.",
      "factIds": ["customs"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "У соседней паромной переправы купцы платили налог за ввоз товаров, называвшийся мытом.",
      "factIds": ["customs"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "Деревянную церковь Троицы в Кожевниках построили приблизительно в 1625 году.",
      "factIds": ["trinity-church"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "Нынешнее пятиглавое здание возвели в 1686–1689 годах",
      "factIds": ["trinity-church"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "колокольню пристроили в 1722 году",
      "factIds": ["trinity-church"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "Расцвет слободы во второй половине XIX века Музей Москвы связывает с Бахрушиными",
      "factIds": ["bakhrushins"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "внедрявшими новые технологии производства кожи и тканей",
      "factIds": ["bakhrushins"],
      "supported": true
    }
  ]
}

{
  "approved": false,
  "issues": [
    "Абзац 4 посвящён истории отдельного служебного корпуса, а не запрошенного главного корпуса; его следует убрать, чтобы не подменять историю выбранного объекта историей соседнего здания."
  ],
  "checks": {
    "substantive": true,
    "subjectAligned": false,
    "audioClear": true
  },
  "paragraphFacts": [
    {
      "paragraph": 1,
      "factIds": ["estate", "architects"]
    },
    {
      "paragraph": 2,
      "factIds": ["exterior", "architects"]
    },
    {
      "paragraph": 3,
      "factIds": ["hall", "galleries", "f7"]
    },
    {
      "paragraph": 4,
      "factIds": ["telegraph"]
    }
  ],
  "claims": [
    {
      "paragraph": 1,
      "text": "Московский почтамт разместился в бывшем дворце Меншикова, который почтовое ведомство арендовало у Лазаревых в 1783 году, а в 1792-м выкупило.",
      "factIds": ["estate"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "Во дворе стояли почтовые экипажи и пассажирские дилижансы.",
      "factIds": ["estate"],
      "supported": true
    },
    {
      "paragraph": 1,
      "text": "В середине XIX века комплекс перестраивал Альберт Кавос.",
      "factIds": ["architects"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Главный корпус открыли в 1912 году.",
      "factIds": ["exterior"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "Его проектировали Леонид Новиков и Оскар Мунц",
      "factIds": ["architects"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "братья Веснины заменили византийское оформление фасада романским.",
      "factIds": ["architects"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "На фасаде установлены круглые часы",
      "factIds": ["exterior"],
      "supported": true
    },
    {
      "paragraph": 2,
      "text": "в комплекс входят проездные арки и внутренние дворы.",
      "factIds": ["exterior"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "На месте прежнего двора устроили операционный зал, перекрытый стеклом на стальном каркасе.",
      "factIds": ["hall"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "Для посетителей установили дубовые стойки.",
      "factIds": ["hall"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "На втором и третьем этажах зал окружают галереи с ажурными ограждениями",
      "factIds": ["galleries"],
      "supported": true
    },
    {
      "paragraph": 3,
      "text": "первый и второй этажи соединяют чугунные винтовые лестницы со сквозным орнаментом ступеней.",
      "factIds": ["f7"],
      "supported": true
    },
    {
      "paragraph": 4,
      "text": "Служебный корпус 1855–1856 годов первоначально строили для почтовых экипажей.",
      "factIds": ["telegraph"],
      "supported": true
    },
    {
      "paragraph": 4,
      "text": "С 1868 года его занимал Московский телеграф",
      "factIds": ["telegraph"],
      "supported": true
    },
    {
      "paragraph": 4,
      "text": "после переезда телеграфа на Тверскую в 1927 году туда вернулась почта.",
      "factIds": ["telegraph"],
      "supported": true
    }
  ]
}

